"""Induction-only preservation of strict equality+definedness, base kept separate."""
import pathlib,json,hashlib,os,subprocess,resource,time
R=pathlib.Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
 base=R/'experiments/prospective_external_family_reset_defined_v1_2026-10-18';receipt=json.loads((base/'receipt.json').read_text());assert receipt['passed'] and receipt['assertions']==1970;assert all(sha(k)==v for k,v in receipt['bindings'].items());miter=base/'strict_miter.json';doc=json.loads(miter.read_text());cells=doc['modules']['base_miter']['cells'];assert sum(c['type']=='$assert' for c in cells.values())==1970;assert not any(c['type']=='$assume' for c in cells.values());v=R/'experiments/prospective_external_family_source_v2_2026-10-18/source_verification.json';tool=json.loads(v.read_text())['yosys_path'];out=R/'experiments/prospective_external_family_defined_induction_v1_2026-10-18';out.mkdir();env=os.environ.copy();lib=R/'experiments/prospective_external_family_runtime_v1_2026-10-18/tcl-root/usr/lib/x86_64-linux-gnu';env['LD_LIBRARY_PATH']=str(lib)+(os.pathsep+env['LD_LIBRARY_PATH'] if env.get('LD_LIBRARY_PATH') else '')
 commands=[f'read_json "{miter}"','hierarchy -top base_miter','opt_clean','sat -seq 1 -tempinduct-inductonly -maxsteps 2 -enable_undef -set-def-inputs -prove-asserts -verify']
 ys=out/'prove.ys';ys.write_text('\n'.join(commands)+'\n');bindings={str(p):sha(p) for p in [pathlib.Path(__file__).resolve(),base/'receipt.json',base/'terminal_review_v1.json',miter,v,pathlib.Path(tool),ys]};protocol=dict(bindings=bindings,commands=commands,assertions=1970,max_induction_steps=2,AS_limit_bytes=8*2**30,elapsed_timeout=None,scope='Induction-only strict equality and definedness preservation for all paired state/output points, arbitrary defined inputs including reset. Does not establish base by itself. Existing reset-defined bounded base must be independently composed with identical property miter. No arbitrary-power-up or full HDL four-state equivalence claim; original unrestricted proof separate.',strict_unseen_admitted=False)
 (out/'protocol.json').write_text(json.dumps(protocol,indent=2)+'\n')
 def limits():resource.setrlimit(resource.RLIMIT_AS,(8*2**30,8*2**30))
 tick=time.perf_counter()
 with (out/'prove.log').open('x') as log:
  child=subprocess.Popen([tool,'-Q','-T','-s',str(ys)],cwd=out,env=env,stdout=log,stderr=subprocess.STDOUT,preexec_fn=limits);s=pathlib.Path(f'/proc/{child.pid}/stat').read_text().split(') ',1)[1].split();(out/'live_process.json').write_text(json.dumps(dict(pid=child.pid,startticks=s[19]))+'\n');print('DEFINED_INDUCTION_CHILD',child.pid,s[19],flush=True);code=child.wait()
 text=(out/'prove.log').read_text();passed=code==0 and 'Induction step proven: SUCCESS!' in text;assert all(sha(k)==v for k,v in bindings.items());result=dict(status='defined_equality_inductive_step_pass' if passed else 'defined_equality_inductive_step_not_proven',bindings=bindings,exit_status=code,passed=passed,process_seconds=time.perf_counter()-tick,log_sha256=sha(out/'prove.log'),scope=protocol['scope'],strict_unseen_admitted=False,original_unrestricted_equivalence_satisfied=False)
 (out/'receipt.json').write_text(json.dumps(result,indent=2)+'\n');print('DEFINED_INDUCTION_TERMINAL',code,passed,flush=True)
if __name__=='__main__':main()
